#!/usr/bin/env python
"""Generate the version of the jax-healpy logo for the dark theme.

The dark version is derived from the logo generated by ``make-logo.py``, so that both
versions show the same CMB pattern: the white background inside the Mollweide ellipse
becomes black, and the gray outlines of the letters and of the ellipse become white.

Usage::

    uv run python docs/logo/make-dark-logo.py
"""

import argparse
from pathlib import Path

import numpy as np
from PIL import Image

SCRIPT_DIR = Path(__file__).parent

# Colors of the logo generated by make-logo.py, and their replacements in the dark version.
OUTLINE_COLOR = [60, 60, 60]
OUTLINE_COLOR_DARK = [255, 255, 255]
BACKGROUND_COLOR_DARK = [0, 0, 0]

# Tolerance on the white background, as in make-logo.py. The CMB pixels close to zero are
# nearly white too, but none of them is that close to white.
BACKGROUND_TOLERANCE = 8


def make_dark_logo(input_file: str | Path, output_file: str | Path) -> np.ndarray:
    """Convert the logo to its dark version and return the RGBA image."""
    data = np.array(Image.open(input_file).convert('RGBA'))
    rgb = data[:, :, :3]
    is_opaque = data[:, :, 3] > 0
    is_background = is_opaque & np.all(rgb > 255 - BACKGROUND_TOLERANCE, axis=-1)
    is_outline = is_opaque & np.all(rgb == OUTLINE_COLOR, axis=-1)
    rgb[is_background] = BACKGROUND_COLOR_DARK
    rgb[is_outline] = OUTLINE_COLOR_DARK
    Image.fromarray(data).save(output_file)
    return data


def main() -> None:
    parser = argparse.ArgumentParser(
        description='Generate the jax-healpy logo for the dark theme',
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument('--input', default=SCRIPT_DIR / 'jax-healpy-logo.png', help='Path to the logo')
    parser.add_argument(
        '--output', default=SCRIPT_DIR / 'jax-healpy-logo-dark.png', help='Path to the logo for the dark theme'
    )
    args = parser.parse_args()
    make_dark_logo(args.input, args.output)


if __name__ == '__main__':
    main()
